package android.media; import java.util.*; public class MediaCodec { public static final int INFO_TRY_AGAIN_LATER=-1, BUFFER_FLAG_END_OF_STREAM=4; public static class BufferInfo { public int flags; public long presentationTimeUs; } public ArrayDeque<Long> pts=new ArrayDeque<>(); public ArrayList<Long> releases=new ArrayList<>(); public boolean throwsOnDequeue; public int discarded, negativeCode=-1; public int dequeueOutputBuffer(BufferInfo b,long t){if(throwsOnDequeue)throw new IllegalStateException();if(pts.isEmpty())return negativeCode;long p=pts.remove();b.flags=p<0?4:0;b.presentationTimeUs=p;return 0;} public void releaseOutputBuffer(int id,boolean r){if(r)throw new AssertionError();discarded++;} public void releaseOutputBuffer(int id,long ns){releases.add(ns);} }